.darma-loader-tw-tab-underline { display: flex; flex-direction: column; gap: calc(var(--loader-size, 170px) * .05); width: var(--loader-size, 170px); }
.darma-loader-tw-tab-underline .darma-loader-tw-tab-underline__tabs { display: flex; gap: calc(var(--loader-size, 170px) * .07); }
.darma-loader-tw-tab-underline .darma-loader-tw-tab-underline__tabs i { flex: 1; height: calc(var(--loader-size, 170px) * .07); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color, #6366f1) 25%, transparent); }
.darma-loader-tw-tab-underline .darma-loader-tw-tab-underline__bar { width: 30%; height: calc(var(--loader-size, 170px) * .035); border-radius: 9999px; background: var(--loader-color, #6366f1); animation: darma-loader-tw-tab-underline-twTabSlide calc(var(--loader-speed, 1s) * 2.4) cubic-bezier(.4, 0, .2, 1) infinite; }
@keyframes darma-loader-tw-tab-underline-twTabSlide { 0%, 10% { transform: translateX(0); } 40%, 50% { transform: translateX(118%); } 80%, 90% { transform: translateX(236%); } 100% { transform: translateX(0); } }

